INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''zero waste'' pattern-cutting approach in apparel design?', '["Designing patterns that use 100% of the fabric with little to no leftover scrap, minimizing fabric waste","A production method that uses no fabric at all","A quality standard requiring zero defects in every garment","A finishing process that removes all excess dye from fabric"]'::jsonb, 'Designing patterns that use 100% of the fabric with little to no leftover scrap, minimizing fabric waste', 'Zero-waste pattern cutting is a design approach where pattern pieces are cleverly shaped/arranged to use nearly all of the fabric rectangle, minimizing or eliminating the scrap typically left over between conventional pattern pieces.', 1, '{"zero-waste-pattern"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''block pattern'' (or ''sloper'') in pattern making?', '["A basic, fitted foundational pattern (without style details) used as the starting template to develop new garment designs","The final approved pattern used directly for bulk cutting","A pattern used exclusively for children''s clothing","A block of fabric samples shown to a buyer"]'::jsonb, 'A basic, fitted foundational pattern (without style details) used as the starting template to develop new garment designs', 'A block/sloper is a basic, well-fitted pattern with no style details (no pockets, specific necklines, etc.) that serves as the foundational starting template pattern makers modify to create new, more detailed garment designs.', 1, '{"block-pattern"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''draping'' as a garment pattern development technique, as opposed to ''flat pattern'' drafting?', '["Pinning and shaping fabric directly on a dress form to develop a pattern, as opposed to drafting flat pattern shapes using measurements/rulers on paper","A finishing process applied only after a garment is completely sewn","A method used exclusively for producing knitwear, never woven garments","A synonym for grading a pattern to different sizes"]'::jsonb, 'Pinning and shaping fabric directly on a dress form to develop a pattern, as opposed to drafting flat pattern shapes using measurements/rulers on paper', 'Draping shapes and pins actual fabric directly onto a three-dimensional dress form to develop the pattern by eye/feel, while flat pattern drafting instead calculates and draws pattern shapes on paper using body measurements and geometric rules — two different pattern-development methodologies.', 2, '{"draping-vs-flat-pattern"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''CAD'' (computer-aided design) system used for in apparel pattern making today?', '["Digitally creating, grading, and arranging patterns on screen, replacing much manual paper-based pattern work","Only for designing garment logos and prints, unrelated to pattern shapes","A system used exclusively for factory payroll management","A machine that physically sews garments automatically"]'::jsonb, 'Digitally creating, grading, and arranging patterns on screen, replacing much manual paper-based pattern work', 'CAD software lets pattern makers digitally draft, grade (resize for the size range), and arrange (marker-make) pattern pieces on screen — far faster and more precise than fully manual paper-based methods, and integrates directly with automated cutting equipment.', 1, '{"cad-pattern-making"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is an ''automated cutting machine'' (e.g., a computer-controlled knife or laser cutter) able to do that improves on fully manual cutting?', '["Follow the exact digital marker layout with high precision and speed, reducing cutting errors and improving fabric utilization consistency","Automated cutters can only cut a single fabric layer at a time, unlike manual methods","Automated cutting eliminates the need for any marker or pattern at all","Automated cutters work only with synthetic fabric, never natural fiber"]'::jsonb, 'Follow the exact digital marker layout with high precision and speed, reducing cutting errors and improving fabric utilization consistency', 'Computer-controlled cutting machines follow the digital marker file with high precision, cutting through multiple fabric layers quickly and consistently — reducing human cutting errors and improving both speed and fabric utilization compared to fully manual cutting.', 1, '{"automated-cutting"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''bundling'' in the garment cutting room, after pieces are cut?', '["Grouping cut garment pieces by size/style/bundle number and tying/organizing them for efficient distribution to sewing line operators","A finishing process that adds extra fabric bulk to a garment","The process of folding finished garments for packaging","A quality inspection step checking fabric color consistency"]'::jsonb, 'Grouping cut garment pieces by size/style/bundle number and tying/organizing them for efficient distribution to sewing line operators', 'After cutting, pieces are sorted and grouped into labeled bundles (by size, style, and a tracking number) so sewing line operators receive organized, matched sets of pieces — supporting efficient, trackable work flow through the sewing process.', 1, '{"bundling"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why is bundle tracking (numbering) important for quality control in garment production?', '["If a defect is found in a finished garment, the bundle number allows tracing it back to the specific fabric roll/cutting lay, helping identify and address the root cause","Bundle numbers exist purely for aesthetic labeling with no functional quality purpose","Bundle tracking only matters for accounting, unrelated to quality investigation","Bundle numbers are used exclusively to track worker attendance, unrelated to garment tracking"]'::jsonb, 'If a defect is found in a finished garment, the bundle number allows tracing it back to the specific fabric roll/cutting lay, helping identify and address the root cause', 'Bundle numbers provide traceability — if a quality problem (like a fabric fault or shade issue) is discovered in a finished garment, tracing back through its bundle number can identify which fabric roll/cutting lay it came from, helping isolate and address the root cause rather than guessing.', 2, '{"bundle-tracking"}'::text[]);
